//! Module for wallet structs and types generated by the sync engine from block chain data or to track the wallet's
//! sync status.
//! The wallet state lives in `zingolib_common::wallet` and the sync state in `zingolib_common::sync`. Both are
//! re-exported here. This module keeps the runtime sync mode and the traits a wallet implements to interface with
//! the sync engine.

use tokio::sync::mpsc;
use zcash_protocol::consensus;

use zingo_netutils::lightwallet_protocol::CompactBlock;

use crate::{
    client::FetchRequest,
    engine::WalletBlockOps as _,
    error::{ServerError, SyncModeError},
    scan::compact_blocks::calculate_block_tree_bounds,
    utils::{
        get_compact_block_hash, get_compact_block_height, get_compact_block_prev_hash,
        get_compact_tx_txid,
    },
};

pub mod traits;

pub use zingolib_common::sync::{InitialSyncState, SyncState};
pub use zingolib_common::wallet::*;

/// Sync modes.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SyncMode {
    /// Sync is not running.
    NotRunning,
    /// Sync is held in a paused state and the wallet guard is dropped.
    Paused,
    /// Sync is running.
    Running,
    /// Sync is shutting down.
    Shutdown,
}

impl SyncMode {
    /// Constructor from u8.
    ///
    /// Returns `None` if `mode` is not a valid enum variant.
    pub fn from_u8(mode: u8) -> Result<Self, SyncModeError> {
        match mode {
            0 => Ok(Self::NotRunning),
            1 => Ok(Self::Paused),
            2 => Ok(Self::Running),
            3 => Ok(Self::Shutdown),
            _ => Err(SyncModeError::InvalidSyncMode(mode)),
        }
    }
}

/// Builds the wallet block for a compact block, fetching the tree sizes at its bounds when the
/// block does not carry them.
pub(crate) async fn wallet_block_from_compact_block(
    consensus_parameters: &impl consensus::Parameters,
    fetch_request_sender: mpsc::UnboundedSender<FetchRequest>,
    block: &CompactBlock,
) -> Result<WalletBlock, ServerError> {
    let tree_bounds =
        calculate_block_tree_bounds(consensus_parameters, fetch_request_sender, block).await?;

    Ok(WalletBlock::from_parts(
        get_compact_block_height(block),
        get_compact_block_hash(block),
        get_compact_block_prev_hash(block),
        block.time,
        block.vtx.iter().map(get_compact_tx_txid).collect(),
        tree_bounds,
    ))
}
